import assert from "node:assert/strict";

export function total(price, quantity) {
  if (![price, quantity].every(value => Number.isSafeInteger(value) && value >= 0)) {
    throw new RangeError("Use nonnegative safe integers");
  }
  const result = price * quantity;
  if (!Number.isSafeInteger(result)) throw new RangeError("Total too large");
  return result;
}
assert.equal(total(12, 3), 36);
assert.equal(total(12, 0), 0);
assert.throws(() => total(12, -1), RangeError);
console.log("3 checks passed");

